"""An offline review of unaltered concept sheets, not runtime art exports."""
from pathlib import Path
import json,hashlib
from PIL import Image
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'art/concepts/descent-horror-v1'
SOURCE=ROOT/'art/source/descent-horror-v1'
def entry(ident,title,issue,idea,omen,review,approach,split):
    return dict(id=ident,title=title,issue=issue,idea=idea,omen=omen,review_focus=review,presentation_proposal=approach,split=split,owner_selection=None)
ENTRIES=[
entry('underhound','The Underhound',150,'Opposing rib structures and a sliding tooth plate strain a recognizable hound body.','Pawprints accompanied by rib-like impressions.','Choose how strongly the inner ribs should show through the hide; retain the long head and low stance.','A small number of authored jaw/rib state drawings, with one shared body scale.',[937,800,497]),
entry('borrowed-pack','The Borrowed Pack',150,'Three predatory bodies pull against one continuous hide.','Separate tracks converge into a broad drag mark.','The hide connection reads at illustration size; simplify overlapping legs before any small sprite production.','One grouped creature image plus a tension state; targeting/body count remains undecided.',[962,758,422]),
entry('marrow-shepherd','The Marrow Shepherd',150,'A narrow tending body carries living bone cradles; an abdominal pod holds a forming animal.','An empty wall cradle suggests slow rocking.','Review the nursery gesture and amount of body horror. These shapes do not establish a canonical life cycle.','Closed/open pod drawings and a separate cradle movement, only if selected.',[938,792,496]),
entry('drowned-bell','The Drowned Bell',151,'A hanging living bell reveals heavy inner organs above black water.','Ripples and suspended droplets beneath an empty recess.','The sheet shows body contraction and water relation; upward travel and deep sound require later motion/audio.','Two body states and a separately controlled droplet/ripple layer.',[939,795,422]),
entry('unfolding','The Unfolding',151,'A compact curled animal extends into more jointed lengths than its resting volume could contain.','A narrow opening bears overlapping enormous scrapes.','Compare resting and extended head/rib identity; the long form needs a deliberate presentation beyond a square sprite.','A staged reveal from a fixed ledge with limited body states, not an independently scaled pose atlas.',[944,774,440]),
entry('choir-of-one','The Choir of One',151,'Charred rib-like lamellae open from a single narrow root into an organic fan.','Repeated tracks and passage ribs suggest an absent repeated footfall.','Closed/open silhouettes read distinctly. Multiple voice distances and the omen\'s sound are still directions for later work.','Closed/open drawings with later spatial sound; no audio or combat behaviour added here.',[943,785,472]),
entry('weight','The Weight',151,'A heavy ivory teardrop parts at its lower seams around an implausibly deep interior.','Grit gathers uphill; a coin stands on edge.','Judge the bodily weight and interior depth. Suspended objects imply orbit but do not demonstrate it in a still.','Closed/parted body with separately placed stones, tool and cloth.',[923,789,478]),
entry('open-door','The Open Door',152,'An organic frame contains a familiar chamber viewed from an incompatible perspective.','A reflection contains a frame absent from the solid wall above it.','The painted views suggest fixed interior orientation; an actual turning-frame/fixed-view effect needs a later prototype.','Separate frame states over a held interior image. This is a presence, not an assumed usable exit.',[931,797,426]),
entry('hollow-interval','The Hollow Interval',152,'The hound silhouette returns as flat absence against a visible room.','Falling grit traces a jaw-shaped interruption.','A still black shape can also read as a shadow. The foreground post remains visible; test room/dust interruption and silhouette readability before production.','A room/background mask with separate edge particles may communicate absence; no shader is implemented.',[975,784,420]),
entry('sleeper-beyond','The Sleeper Beyond',152,'A single vast curled finger lies behind vertical dark water, with tiny mining/party scale cues.','Condensation on apparently dry rock suggests upward movement.','The refined blunt nail reads as a finger. An architecture-first reveal needs occlusion/pacing review; its full body, identity and relation to the objective remain unknown.','An environmental background reveal, a water layer and one subtle joint-state change; no boss fight assumed.',[938,797,496]),
]
masters=json.loads((SOURCE/'generation.json').read_text(encoding='utf-8'))
byid={e['id']:e for e in masters['assets']}
REVISED={'drowned-bell':'drowned-bell-revised','sleeper-beyond':'sleeper-beyond-revised'}
for e in ENTRIES:
    ident=REVISED.get(e['id'],e['id']);master=byid[ident]
    e.update(master_id=ident,file=Path(master['review']).name,source=master['source'],sha256=master['sha256'],size=list(Image.open(ROOT/master['review']).size),owner_feedback='Positive overall visual feedback; individual production selection unresolved.')
    if e['id']=='underhound':
        e['production_selection']={'date':'2026-10-25','selected_by':"Codex, at the owner's request",'brief':'docs/underhound-production.md','scope':'First three-pose production subject; runtime art and encounter assignment not yet made.'}
        e['owner_feedback']='Owner delegated the first production choice to Codex; Underhound selected. This does not approve finished sprites or assign a floor/story role.'
    if e['id'] in REVISED:
        e['previous']={key:e[key] for key in ['idea','review_focus','split','size']}
        e['previous'].update(file=e['id']+'.png',source=byid[e['id']]['source'],sha256=byid[e['id']]['sha256'])
        e['owner_feedback']='Owner requested a form revision to remove an unintended anatomical resemblance. Revised draft awaiting review.'
    if e['id']=='drowned-bell':
        e.update(idea='A broad flared living bell holds one angular central clapper above black water.',review_focus='Owner revision: paired sacs replaced by one flat ossified striker and a wider hood. Review the new outline; upward water travel and deep sound remain later work.')
    if e['id']=='sleeper-beyond':
        e.update(idea='A vast broad folded mantle or carapace resembles ruined vaults beyond vertical dark water.',review_focus='Owner revision: the finger shape gives way to asymmetric plates, pleats and broken arches. Full anatomy, identity and relation to the objective remain open.',presentation_proposal='An environmental background reveal, a water layer and one restrained plate movement; no boss fight assumed.')
catalog={'issues':[150,151,152],'date':'2026-10-22','selection_updated':'2026-10-25','status':'Underhound selected first for production at the owner\'s request; the other nine remain pending','scope':'Concept paintings and a production subject choice. No runtime sprites, rigs, EnemyType, stats, encounters or lore assignments.','entries':ENTRIES,'sources':masters['assets']}
(OUT/'catalog.json').write_text(json.dumps(catalog,indent=2)+'\n',encoding='utf-8',newline='\n')
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Depths · Descent into the grotesque</title><style>
@font-face{font-family:Field;src:url('../../fonts/source-sans-3/SourceSans3-Variable.ttf')}*{box-sizing:border-box}:root{color-scheme:dark;font:17px/1.5 Field,system-ui,sans-serif;color:#dfd7c4;background:#151915}body{margin:0}main{max-width:1300px;margin:auto;padding:24px clamp(14px,3vw,32px) 60px}h1,h2,h3{font-weight:500;line-height:1.16}h1{font-size:clamp(29px,5vw,44px)}h2{font-size:28px}h3{font-size:22px}p{color:#b9bdac;max-width:90ch}a{color:#dbc087}button,select{font:inherit;min-height:44px;max-width:100%;padding:8px 12px;background:#283128;color:inherit;border:1px solid #646d54;border-radius:3px;cursor:pointer}button[aria-pressed=true]{background:#4a4a33;border-color:#dbc087}button:focus-visible,select:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #dbc087;outline-offset:3px}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin:18px 0}label{display:flex;align-items:center;flex-wrap:wrap;gap:7px;min-height:44px}.badge{color:#d6bc85;letter-spacing:.1em;font-size:14px}.note{border-left:2px solid #837b54;padding:0 0 0 14px}.stage{position:relative;overflow:hidden;background:#111511;border:1px solid #56604a;isolation:isolate}.stage img{position:absolute;max-width:none;display:block}.summary{display:grid;grid-template-columns:1fr 1fr;gap:20px}.small-study{max-width:100%;height:auto;display:block;border:1px solid #4b563f}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,270px),1fr));gap:14px}.card{min-width:0;background:#20271e;border:1px solid #43503c;padding:12px}.card .stage{pointer-events:none}.card h3{margin:12px 0 5px}.card p{font-size:15px}.card button{width:100%;text-align:left}.ref{background:#202820;border:1px solid #46513d;padding:12px;min-width:0}.ref img{width:128px;height:128px;object-fit:contain;image-rendering:pixelated;background:#111711}.ref-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:12px}.ref h3{font-size:19px}.reference-main{max-width:128px}.caption{font-size:15px;color:#b0b6a3}details{margin:16px 0;border-top:1px solid #46503c;padding-top:10px}summary{min-height:44px;cursor:pointer;color:#dbc087}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.5 Field,system-ui}#sources a{overflow-wrap:anywhere}[hidden]{display:none!important}@media(max-width:700px){.summary{grid-template-columns:1fr}.controls{gap:7px}.grid{grid-template-columns:1fr}h1{margin-top:14px}}
</style></head><body><main><header><span class="badge">DEPTHS · CONCEPT EXPLORATION · 150 / 151 / 152</span><h1>Descent into the grotesque</h1><p>Ten draft beings: familiar predators become impossible bodies, then space, absence and scale become the encounter. Dark and gritty throughout. Underhound is selected as the first production subject. These paintings remain concepts; story identities, floors and finished sprites remain open.</p><p><a href="../../../docs/descent-horror-concepts.md">Review notes and open decisions</a> · <a href="../../../docs/enemy-art-direction.md">Art direction</a> · <a href="../../../docs/underhound-production.md">Underhound production brief</a> · <a href="#comparison">Compare the descent</a></p></header>
<div class="controls" aria-label="Concept batches"><button class="batch" data-batch="all" aria-pressed="true">All drafts</button><button class="batch" data-batch="150" aria-pressed="false">Wrong animals</button><button class="batch" data-batch="151" aria-pressed="false">Impossible bodies</button><button class="batch" data-batch="152" aria-pressed="false">Near the objective</button></div>
<div class="controls"><label>Concept <select id="concept"></select></label><button id="previous">Previous</button><button id="next">Next</button><label id="variant-label" hidden>Draft <select id="variant"><option value="current">Revised</option><option value="previous">Previous</option></select></label><label>View <select id="view"><option value="sheet">Full sheet</option><option value="main">Main painting</option><option value="state">Revealing state</option><option value="omen">Omen / context</option><option value="small">Shape studies</option></select></label><a id="original" target="_blank" rel="noopener">Open original sheet</a></div>
<h2 id="title"></h2><p id="idea"></p><div id="stage" class="stage"><img id="art" alt="Selected creature concept sheet"></div><p class="caption">The view control magnifies regions of the original painting. It does not create production cutouts or registered animation frames.</p><div class="summary"><div><h3>Omen</h3><p id="omen"></p><h3>Review focus</h3><p id="focus"></p></div><div><h3>Possible later presentation</h3><p id="approach"></p><p class="note" id="selection">Production selection pending. Water direction, orbit, voices and held interior views are still-image proposals; this gallery does not demonstrate live animation, sound or game integration.</p></div></div>
<h3>Small-view study</h3><p class="caption">A 320px-wide display of the complete painted shape-study strip. For contextual beings, shape alone does not explain the encounter.</p><div id="small" class="stage" style="width:320px;max-width:100%"><img alt="Painted shape studies at a small display size"></div>
<h2 id="comparison">Compare the descent</h2><p>Look for a relationship between the early hounds and later anatomy without turning every being into the same creature. The final three explore incompatible perspective, absence and scale separately.</p><div id="gallery" class="grid"></div><h2>Existing family reference</h2><div class="ref-grid"><div class="ref"><img src="../../enemies/monsters-v1/breach-hound/idle.png" alt="Existing native128 breach hound"><h3>Existing breach hound</h3><p class="caption">Live native128 artwork. Concept detail and new shapes have not been converted into this production format.</p></div><div class="ref"><img src="../../enemies/cave-simple-v1/rat/idle.png" alt="Existing upper-mine rat"><h3>Grounded starting point</h3><p class="caption">The ordinary creature establishes a physical world before the descent starts breaking it.</p></div></div>
<details><summary>Earlier drafts</summary><p class="caption">The owner requested a single bell clapper and a different Sleeper silhouette. The revised drafts preserve those earlier paintings for comparison; their production selection is still open.</p><p><a href="drowned-bell.png">Bell with paired organs</a> · <a href="sleeper-beyond.png">Sleeper finger draft</a> · <a href="sleeper-beyond-first.png">First claw-like Sleeper</a></p></details>
<details><summary>Exact prompts and original masters</summary><div id="sources"></div></details></main><script>
const DATA=__DATA__,by=id=>document.getElementById(id),cache=new Map(),requested=new URLSearchParams(location.search).get('concept');window.reviewState={batch:'all',id:DATA.entries.some(e=>e.id===requested)?requested:'underhound',view:'sheet',variant:'current'};let ticket=0;
function img(src){if(!cache.has(src)){const i=new Image();i.src=src;cache.set(src,i.decode().then(()=>i))}return cache.get(src)}
function rect(e,view){const [x,y,mid]=e.split,[w,h]=e.size;return view==='main'?[0,0,x,y]:view==='state'?[x,0,w-x,mid]:view==='omen'?[x,mid,w-x,y-mid]:view==='small'?[0,y,w,h-y]:[0,0,w,h]}
function crop(stage,e,view){const [x,y,w,h]=rect(e,view),i=stage.querySelector('img');stage.style.aspectRatio=w+'/'+h;i.style.width=(e.size[0]/w*100)+'%';i.style.height=(e.size[1]/h*100)+'%';i.style.left=(-x/w*100)+'%';i.style.top=(-y/h*100)+'%';i.src=e.file}
function entries(){return DATA.entries.filter(e=>reviewState.batch==='all'||String(e.issue)===reviewState.batch)}
async function paint(){const mine=++ticket,e=DATA.entries.find(e=>e.id===reviewState.id),old=!!e.previous&&reviewState.variant==='previous',v=old?{...e,...e.previous}:e;await img(v.file);if(mine!==ticket)return;by('concept').value=e.id;by('variant-label').hidden=!e.previous;by('variant').value=old?'previous':'current';by('title').textContent=e.title+(e.previous?(old?' · previous draft':' · revised draft'):'');by('idea').textContent=v.idea;by('omen').textContent=e.omen;by('focus').textContent=old?'Earlier draft retained for comparison. The owner requested a new silhouette; select Revised to inspect that proposal.':e.review_focus;by('approach').textContent=e.presentation_proposal;by('selection').textContent=e.production_selection?'Selected first for production by Codex at the owner’s request. Three registered poses; finished sprite and encounter review still to come.':'Production selection pending. Motion and sound remain presentation proposals.';by('original').href=v.file;by('art').alt=e.title+' · '+reviewState.view+(old?' · previous':'');crop(by('stage'),v,reviewState.view);crop(by('small'),v,'small');return Promise.all([by('art').decode(),by('small').querySelector('img').decode()]).catch(error=>{if(mine===ticket)throw error})}
function render(){window.viewReady=paint();return window.viewReady}
function choose(id){reviewState.id=id;reviewState.variant='current';return render()}
function filter(batch){reviewState.batch=batch;for(const b of document.querySelectorAll('.batch'))b.setAttribute('aria-pressed',String(b.dataset.batch===batch));by('concept').replaceChildren(...entries().map(e=>new Option(e.title,e.id)));for(const c of document.querySelectorAll('.concept-card'))c.hidden=batch!=='all'&&c.dataset.batch!==batch;if(!entries().some(e=>e.id===reviewState.id)){reviewState.id=entries()[0].id;reviewState.variant='current'}render()}
by('variant').onchange=()=>{reviewState.variant=by('variant').value;render()};
for(const b of document.querySelectorAll('.batch'))b.onclick=()=>filter(b.dataset.batch);by('concept').onchange=()=>choose(by('concept').value);by('view').onchange=()=>{reviewState.view=by('view').value;render()};for(const [id,step]of [['previous',-1],['next',1]])by(id).onclick=()=>{const a=entries();choose(a[(a.findIndex(e=>e.id===reviewState.id)+step+a.length)%a.length].id)};
for(const e of DATA.entries){const c=document.createElement('article');c.className='card concept-card';c.dataset.batch=String(e.issue);c.dataset.id=e.id;const b=document.createElement('button'),stage=document.createElement('div'),i=new Image(),h=document.createElement('h3'),p=document.createElement('p');stage.className='stage';i.alt=e.title+' main painting preview';stage.append(i);crop(stage,e,'main');h.textContent=e.title;p.textContent=e.idea;b.append(stage,h);b.onclick=()=>{if(reviewState.batch!=='all'&&reviewState.batch!==String(e.issue))filter('all');choose(e.id);by('title').scrollIntoView({behavior:'smooth',block:'start'})};c.append(b,p);by('gallery').append(c)}
for(const e of DATA.sources){const d=document.createElement('details'),s=document.createElement('summary'),a=document.createElement('a'),p=document.createElement('pre');s.textContent=e.title;a.href='../../../'+e.source;a.textContent='Original master · '+e.sha256.slice(0,12);p.textContent=e.prompt;d.append(s,a,p);by('sources').append(d)}
filter('all');window.artReadyPromise=Promise.all([window.viewReady,...DATA.entries.map(e=>img(e.file)),...Array.from(document.querySelectorAll('.ref img')).map(i=>i.decode())]);
</script></body></html>'''
(OUT/'inspector.html').write_text(html.replace('__DATA__',json.dumps(catalog)),encoding='utf-8',newline='\n')
print('HORROR_CONCEPT_REVIEW:',len(ENTRIES),'drafts; original sheets and prompts retained')
